/**
 * Merge raw Google Maps scrape output → typed TS module.
 *
 * Usage: node scripts/merge-destination-enrichment.mjs
 *
 * Reads data/generated/destination-enrichment-raw.json, writes
 * data/destinationEnrichment.ts (generated — do not edit by hand).
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const RAW_FILE = path.join(__dirname, '../data/generated/destination-enrichment-raw.json');
const OUT_FILE = path.join(__dirname, '../data/destinationEnrichment.ts');

const raw = JSON.parse(fs.readFileSync(RAW_FILE, 'utf8'));
const entries = Object.values(raw).filter(e => e?.gmRating || e?.photos?.length || e?.lat);

const lines = [];
lines.push('// Auto-generated by scripts/merge-destination-enrichment.mjs — do not edit by hand.');
lines.push('// Google Maps public data (rating, review count, photos, refined coords) per destination.');
lines.push('');
lines.push('export interface DestinationEnrichment {');
lines.push('  id: string;');
lines.push('  gmRating?: number;');
lines.push('  gmReviewCount?: number;');
lines.push('  gmHours?: string;');
lines.push('  gmUrl?: string;');
lines.push('  photos: string[];');
lines.push('  lat?: number;');
lines.push('  lng?: number;');
lines.push('}');
lines.push('');
lines.push('export const DESTINATION_ENRICHMENT: Record<string, DestinationEnrichment> = {');

for (const e of entries.sort((a, b) => a.id.localeCompare(b.id))) {
  const p = [];
  if (typeof e.gmRating === 'number') p.push(`gmRating: ${e.gmRating}`);
  if (typeof e.gmReviewCount === 'number') p.push(`gmReviewCount: ${e.gmReviewCount}`);
  if (e.gmHours) p.push(`gmHours: ${JSON.stringify(e.gmHours)}`);
  if (e.gmUrl) p.push(`gmUrl: ${JSON.stringify(e.gmUrl)}`);
  p.push(`photos: ${JSON.stringify(e.photos || [])}`);
  if (typeof e.lat === 'number') p.push(`lat: ${e.lat}`);
  if (typeof e.lng === 'number') p.push(`lng: ${e.lng}`);
  lines.push(`  '${e.id}': { id: '${e.id}', ${p.join(', ')} },`);
}

lines.push('};');
lines.push('');
fs.writeFileSync(OUT_FILE, lines.join('\n'));
console.log(`Merged ${entries.length} entries → data/destinationEnrichment.ts`);
